private data class PendingCarryoverOwner(
    val uid: String,
    val generation: Long,
    val businessDay: LocalDate,
)

private var pendingCarryoverOwner: PendingCarryoverOwner? = null
internal var pendingCarryoverJob: Job? = null

fun stopPendingCarryoverRetry() {
    pendingCarryoverJob?.cancel()
    pendingCarryoverJob = null
    pendingCarryoverOwner = null
}

internal fun checkAndSchedulePendingCarryoverRetry(dailyTask: DailyTaskStatus?) {
    if (dailyTask == null || dailyTask.carryoverReady != false) {
        stopPendingCarryoverRetry()
        return
    }

    val targetUid = repository.currentUserId() ?: run {
        stopPendingCarryoverRetry()
        return
    }
    val targetGeneration = SessionCacheManager.currentGeneration()
    val targetDay = repository.businessDay()

    val newOwner = PendingCarryoverOwner(targetUid, targetGeneration, targetDay)
    if (pendingCarryoverJob?.isActive == true) {
        if (pendingCarryoverOwner == newOwner) {
            return
        }
        stopPendingCarryoverRetry()
    }

    pendingCarryoverOwner = newOwner
    pendingCarryoverJob = viewModelScope.launch {
        try {
            for (delayMs in PENDING_CARRYOVER_BACKOFF_MS) {
                delay(delayMs)
                if (repository.currentUserId() != targetUid ||
                    SessionCacheManager.currentGeneration() != targetGeneration ||
                    repository.businessDay() != targetDay
                ) {
                    break
                }
                try {
                    val freshRaw = repository.getMyDailyTaskStatus()
                    if (repository.currentUserId() != targetUid ||
                        SessionCacheManager.currentGeneration() != targetGeneration ||
                        repository.businessDay() != targetDay
                    ) {
                        break
                    }
                    val freshStatus = freshRaw.forCurrentUi(targetDay.toString())
                    if (freshStatus != null) {
                        _uiState.update { state ->
                            state.copy(
                                dailyTask = freshStatus,
                                missedStreak = freshStatus.missedStreak
                            )
                        }
                        if (freshStatus.carryoverReady != false) {
                            break
                        }
                    }
                } catch (e: CancellationException) {
                    throw e
                } catch (_: Exception) {
                    // Tiếp tục thử lần sau
                }
            }
        } finally {
            if (pendingCarryoverJob === coroutineContext[Job]) {
                pendingCarryoverJob = null
                pendingCarryoverOwner = null
            }
        }
    }
}

