    fun testPendingThrough120sThenReadyTransitionsAutomaticallyWithoutManualRefresh() = runTest(testScheduler) {
        val testDate = "2026-10-30"
        val dayRef = AtomicReference(LocalDate.parse(testDate))
        val isReadyOnServer = AtomicBoolean(false)
        val pollCount = AtomicInteger(0)

        val client = createTestClient { req ->
            if (req.url.encodedPath.contains("get_my_daily_task_status")) {
                pollCount.incrementAndGet()
