private suspend fun advanceToAttempt(
    scheduler: TestCoroutineScheduler,
    delayMs: Long,
    targetCount: Int,
    counter: AtomicInteger
) {
    scheduler.advanceTimeBy(delayMs)
    scheduler.runCurrent()
    withTimeout(5000) {
        while (counter.get() < targetCount) {
            kotlinx.coroutines.delay(10)
        }
    }
}

